  },
  'stripe_live_key': {
    cost: 5000,
    downtime: 1,
    complexity: 2,
    base_risk_reduction: 30,
    remediation: 'Rotate exposed live key and enable secret scanning.'
  },
  'aws_access_key': {
    cost: 5000,
    downtime: 1,
    complexity: 2,
    base_risk_reduction: 30,
    remediation: 'Rotate exposed AWS key and enforce secrets management.'
  },
  'google_api_key': {
    cost: 5000,
