    downtime: 2,
    complexity: 5,
    base_risk_reduction: 40,
    remediation: 'Require clinician approval for medication dosing recommendations.'
  },
  'autonomous_discharge': {
    cost: 12000,
    downtime: 2,
    complexity: 4,
    base_risk_reduction: 35,
    remediation: 'Block autonomous discharge decisions without clinical review.'
  },
  'clinician_bypass': {
    cost: 12000,
    downtime: 2,
    complexity: 4,
    base_risk_reduction: 35,
    remediation: 'Enforce clinician sign-off workflow.'
  },
  'alarm_override': {
    cost: 15000,
    downtime: 3,
    complexity: 5,
    base_risk_reduction: 40,
    remediation: 'Prevent AI or user prompts from disabling clinical safety alarms.'
  },
  'unauthorized_disclosure': {
    cost: 15000,
    downtime: 2,
    complexity: 4,
    base_risk_reduction: 38,
    remediation: 'Block unauthorized patient data disclosure workflows.'
  }
};

const SEV_MULT = {
  critical: 1.5,
  high: 1.0,
  medium: 0.6,
  low: 0.3
};

const PILLAR_WEIGHTS = {
  Trust: 1.0,
  Identity: 1.0,
  Privacy: 1.2,
  Protection: 1.0,
  Safety: 1.4,
  Security: 1.0
};

const findings = Array.isArray(ctx.findings) ? ctx.findings : [];

const actions = findings.map((f, idx) => {
  const tmpl = ACTION_TEMPLATES[f.type] || {
    cost: 10000,
    downtime: 2,
    complexity: 4,
    base_risk_reduction: 20,
    remediation: 'Apply generic remediation control.'
  };

  const sevMult = SEV_MULT[f.severity] || 0.5;
  const pillars = f.tippss_mapping || [];
  const tippssWeight = pillars.reduce((s, p) => s + (PILLAR_WEIGHTS[p] || 1), 0);

  const isPQ =
    f.agent === 'pq_benchmark' ||
    f.type === 'classical_key_exchange' ||
    f.type === 'classical_signature' ||
    f.type === 'deprecated_tls_version' ||
    f.type === 'weak_hash' ||
    f.type === 'long_lifetime_classical_crypto';

  const isSafety = pillars.includes('Safety');

  const benefit =
    Math.round(tmpl.base_risk_reduction * sevMult) +
    (isPQ ? 25 : 0) +
    (isSafety ? 20 : 0) +
    Math.round(tippssWeight * 10);

  return {
    id: `A${idx + 1}`,
    finding_index: idx,
    finding_type: f.type,
    severity: f.severity,
    source_agent: f.agent,
    description: f.detail,
    remediation: tmpl.remediation,
    risk_reduction: Math.round(tmpl.base_risk_reduction * sevMult),
    cost_usd: tmpl.cost,
    downtime_hrs: tmpl.downtime,
    complexity: tmpl.complexity,
    pqc_urgency: isPQ ? 25 : 0,
    safety_criticality: isSafety ? 20 : 0,
    tippss_weight: Math.round(tippssWeight * 10),
    tippss_pillars: pillars,
    optimization_benefit: benefit,
    value_density: Number((benefit / Math.max(1, tmpl.cost / 1000 + tmpl.downtime * 2 + tmpl.complexity)).toFixed(3))
  };
});

// ------------------------------------------------------------------
// No actions case
// ------------------------------------------------------------------
if (actions.length === 0) {
  ctx.qiro = {
    algorithm: 'CPU-based Quantum-Inspired Simulated Annealing (Ising/QUBO-style)',
    qiro_version: '2.0.0',
    selected_actions: [],
    excluded_actions: [],
    total_candidate_actions: 0,
    selection_count: 0,
    total_cost_usd: 0,
    total_downtime_hrs: 0,
    total_risk_reduction: 0,
    budget_constraint_usd: budget,
    downtime_constraint_hrs: maxDowntime,
    budget_remaining_usd: budget,
    downtime_remaining_hrs: maxDowntime,
    budget_utilization_pct: 0,
    downtime_utilization_pct: 0,
    status: 'no_actions_needed',
    constraint_explanation: 'No remediation actions were needed because the system produced no findings.',
    migration_phase_plan: {
      phase_1_immediate_0_6mo: [],
      phase_2_transitional_6_18mo: [],
      phase_3_full_pq_18_36mo: []
    },
    message: 'No remediation actions required. System is already clean for the tested controls.'
  };

  return { json: ctx };
}

// ------------------------------------------------------------------
// Step 2: Objective / energy function
// ------------------------------------------------------------------
// Maximize:
//   risk_reduction + PQ urgency + safety criticality + TIPPSS impact
//
// Penalize:
//   cost, downtime, complexity, and hard constraint violations
// ------------------------------------------------------------------
function evaluate(selection, actions, budget, maxDowntime) {
  let totalCost = 0;
  let totalDowntime = 0;
  let totalBenefit = 0;
  let totalComplexityPenalty = 0;

  for (let i = 0; i < selection.length; i++) {
    if (selection[i] === 1) {
      const a = actions[i];

      totalCost += a.cost_usd;
      totalDowntime += a.downtime_hrs;
      totalBenefit += a.optimization_benefit;
      totalComplexityPenalty += a.complexity * 0.5;
    }
  }

  let constraintPenalty = 0;

  if (totalCost > budget) {
    constraintPenalty += ((totalCost - budget) / 1000) * 100;
  }

  if (totalDowntime > maxDowntime) {
    constraintPenalty += (totalDowntime - maxDowntime) * 100;
  }

  return totalBenefit - totalComplexityPenalty - constraintPenalty;
}

function totalsForSelection(selection, actions) {
  let totalCost = 0;
  let totalDowntime = 0;
  let totalRiskReduction = 0;
  let totalBenefit = 0;

  for (let i = 0; i < selection.length; i++) {
    if (selection[i] === 1) {
      totalCost += actions[i].cost_usd;
      totalDowntime += actions[i].downtime_hrs;
      totalRiskReduction += actions[i].risk_reduction;
      totalBenefit += actions[i].optimization_benefit;
    }
  }

  return {
    totalCost,
    totalDowntime,
    totalRiskReduction,
    totalBenefit
  };
}

// ------------------------------------------------------------------
// Step 3: Simulated annealing
// ------------------------------------------------------------------
const N = actions.length;
const iterations = Math.min(3000, 200 + N * 80);
let T = 100.0;
const cooling = 0.995;

// Greedy initial state: select high value-density actions that fit constraints.
let current = new Array(N).fill(0);

const sortedIdx = [...Array(N).keys()].sort((a, b) => {
  return actions[b].value_density - actions[a].value_density;
});

let runningCost = 0;
let runningDowntime = 0;

for (const i of sortedIdx) {
  if (
    runningCost + actions[i].cost_usd <= budget &&
    runningDowntime + actions[i].downtime_hrs <= maxDowntime
  ) {
    current[i] = 1;
    runningCost += actions[i].cost_usd;
    runningDowntime += actions[i].downtime_hrs;
  }
}

let currentScore = evaluate(current, actions, budget, maxDowntime);
let best = [...current];
let bestScore = currentScore;

// Main SA loop
for (let iter = 0; iter < iterations; iter++) {
  const idx = Math.floor(Math.random() * N);
  const neighbor = [...current];

  neighbor[idx] = 1 - neighbor[idx];

  const neighborTotals = totalsForSelection(neighbor, actions);

  // Hard guard: avoid accepting impossible states unless we are evaluating penalty.
  // This keeps final plan feasible and easier to explain to hospital users.
  const feasible =
    neighborTotals.totalCost <= budget &&
    neighborTotals.totalDowntime <= maxDowntime;

  const neighborScore = evaluate(neighbor, actions, budget, maxDowntime);
  const delta = neighborScore - currentScore;

  if (feasible && (delta > 0 || Math.random() < Math.exp(delta / T))) {
    current = neighbor;
    currentScore = neighborScore;

    if (currentScore > bestScore) {
      best = [...current];
      bestScore = currentScore;
    }
  }

  T *= cooling;
}

// ------------------------------------------------------------------
// Step 4: Build selected actions
// ------------------------------------------------------------------
let selectedActions = [];
let totalCost = 0;
let totalDowntime = 0;
let totalRiskReduction = 0;

for (let i = 0; i < best.length; i++) {
  if (best[i] === 1) {
    selectedActions.push({ ...actions[i] });
    totalCost += actions[i].cost_usd;
    totalDowntime += actions[i].downtime_hrs;
    totalRiskReduction += actions[i].risk_reduction;
  }
}

// Sort selected actions by urgency and value
selectedActions.sort((a, b) => {
  const ua =
    a.pqc_urgency +
    a.safety_criticality +
    (SEV_MULT[a.severity] || 0.5) * 100 +
    a.tippss_weight;

  const ub =
    b.pqc_urgency +
    b.safety_criticality +
    (SEV_MULT[b.severity] || 0.5) * 100 +
    b.tippss_weight;

  return ub - ua;
});

selectedActions.forEach((a, i) => {
  a.priority_rank = i + 1;
  a.selection_reason = buildSelectionReason(a);
});

function buildSelectionReason(a) {
  const reasons = [];

  if (a.severity === 'critical') {
    reasons.push('critical severity');
  }

  if (a.pqc_urgency > 0) {
    reasons.push('post-quantum migration urgency');
  }

  if (a.safety_criticality > 0) {
    reasons.push('clinical safety impact');
  }

  if (a.tippss_weight >= 30) {
    reasons.push('high TIPPSS impact');
  }

  if (a.cost_usd <= 10000) {
    reasons.push('low-cost quick win');
  }

  if (reasons.length === 0) {
    reasons.push('best optimization value under current constraints');
  }

  return `Selected because of ${reasons.join(', ')}.`;
}

// ------------------------------------------------------------------
// Step 5: Build excluded actions with reasons
// ------------------------------------------------------------------
const selectedIds = new Set(selectedActions.map(a => a.id));
const remainingBudget = Math.max(0, budget - totalCost);
const remainingDowntime = Math.max(0, maxDowntime - totalDowntime);

const excludedActions = actions
  .filter(a => !selectedIds.has(a.id))
  .map(a => {
    let reason = 'Lower optimization priority than selected actions under the current constraints.';

    if (a.cost_usd > budget) {
      reason = 'Not selected because this single action exceeds the total available budget.';
    } else if (a.downtime_hrs > maxDowntime) {
      reason = 'Not selected because this single action exceeds the allowed service downtime.';
    } else if (a.cost_usd > remainingBudget && a.downtime_hrs > remainingDowntime) {
      reason = 'Not selected because it exceeds the remaining budget and remaining downtime after higher-priority actions.';
    } else if (a.cost_usd > remainingBudget) {
      reason = 'Not selected because it exceeds the remaining budget after higher-priority actions.';
    } else if (a.downtime_hrs > remainingDowntime) {
      reason = 'Not selected because it exceeds the remaining downtime after higher-priority actions.';
    }

    return {
      id: a.id,
      finding_index: a.finding_index,
      finding_type: a.finding_type,
      severity: a.severity,
      description: a.description,
      remediation: a.remediation,
      risk_reduction: a.risk_reduction,
      cost_usd: a.cost_usd,
      downtime_hrs: a.downtime_hrs,
      pqc_urgency: a.pqc_urgency,
      safety_criticality: a.safety_criticality,
      tippss_weight: a.tippss_weight,
      tippss_pillars: a.tippss_pillars,
      optimization_benefit: a.optimization_benefit,
      reason
    };
  });

// ------------------------------------------------------------------
// Step 6: Compute phase plan
// ------------------------------------------------------------------
const phases = {
  phase_1_immediate_0_6mo: selectedActions
    .filter(a => a.severity === 'critical' || a.pqc_urgency >= 25)
    .slice(0, 5),

  phase_2_transitional_6_18mo: selectedActions
    .filter(a => a.severity === 'high' && a.pqc_urgency < 25),

  phase_3_full_pq_18_36mo: selectedActions
    .filter(a => a.severity !== 'critical' && a.severity !== 'high')
};

// ------------------------------------------------------------------
// Step 7: Human-readable constraint explanation
// ------------------------------------------------------------------
let constraintExplanation = '';

if (selectedActions.length === actions.length) {
  constraintExplanation =
    `QIRO selected all ${actions.length} remediation actions because they fit within the available budget of $${budget.toLocaleString()} and allowed downtime of ${maxDowntime}h.`;
} else if (selectedActions.length === 0) {
  constraintExplanation =
    `QIRO selected no actions because none of the candidate remediations fit within the available budget of $${budget.toLocaleString()} and allowed downtime of ${maxDowntime}h.`;
} else {
  constraintExplanation =
    `QIRO selected ${selectedActions.length} of ${actions.length} actions that maximize risk reduction, PQ urgency, safety impact, and TIPPSS improvement while staying within the available budget of $${budget.toLocaleString()} and allowed downtime of ${maxDowntime}h. ${excludedActions.length} actions were deferred because of budget, downtime, or lower optimization priority.`;
}

const budgetUtilization =
  budget > 0 ? Math.round((totalCost / budget) * 100) : 0;

const downtimeUtilization =
  maxDowntime > 0 ? Math.round((totalDowntime / maxDowntime) * 100) : 0;

// ------------------------------------------------------------------
// Step 8: Final QIRO output
// ------------------------------------------------------------------
ctx.qiro = {
  algorithm: 'CPU-based Quantum-Inspired Simulated Annealing (Ising/QUBO-style)',
  qiro_version: '2.0.0',

  // Technical optimizer metadata
  iterations_run: iterations,
  final_temperature: T.toFixed(4),
  optimization_score: Math.round(bestScore),
  objective:
    'Maximize risk reduction + PQ urgency + safety criticality + TIPPSS impact, constrained by budget and downtime.',

  // Candidate and selected actions
  total_candidate_actions: N,
  selected_actions: selectedActions,
  excluded_actions: excludedActions,
  selection_count: selectedActions.length,
  excluded_count: excludedActions.length,

  // Constraint values
  budget_constraint_usd: budget,
  downtime_constraint_hrs: maxDowntime,
  total_cost_usd: totalCost,
  total_downtime_hrs: totalDowntime,
  budget_remaining_usd: Math.max(0, budget - totalCost),
  downtime_remaining_hrs: Math.max(0, maxDowntime - totalDowntime),
  budget_utilization_pct: budgetUtilization,
  downtime_utilization_pct: downtimeUtilization,

  // Optimization result
  total_risk_reduction: totalRiskReduction,
  migration_phase_plan: phases,
  constraint_explanation: constraintExplanation,

  // Frontend-friendly message
  message:
    `QIRO selected ${selectedActions.length} of ${N} candidate remediation actions, achieving ${totalRiskReduction} total risk reduction within $${totalCost.toLocaleString()} cost and ${totalDowntime}h downtime. Budget remaining: $${Math.max(0, budget - totalCost).toLocaleString()}; downtime remaining: ${Math.max(0, maxDowntime - totalDowntime)}h.`
};

return { json: ctx };

